<template>
  <q-input
    outlined
    dense
    v-model="params.order_date"
    @update:model-value="fetchData"
    :clearable="true"
    class="q-mr-sm"
    style="width: 227px; height: 40px"
  >
    <template v-slot:append>
      <q-icon name="event" class="cursor-pointer">
        <q-popup-proxy cover transition-show="scale" transition-hide="scale">
          <q-date
            @update:model-value="fetchData"
            v-model="params.order_date"
            mask="YYYY-MM-DD"
          >
            <div class="row items-center justify-end">
              <q-btn v-close-popup label="Close" color="primary" flat />
            </div>
          </q-date>
        </q-popup-proxy>
      </q-icon>
    </template>
  </q-input>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useDashboardASNStore } from '../../store/index';
export default defineComponent({
  mixins: [],
  props: {},
  methods: {
    fetchData(value: any) {
      this.params.order_date = value;
      this.resetPagination();
      this.getAsnData();
    },
  },
  setup() {
    const date = ref();
    const store = storeToRefs(useDashboardASNStore());
    const { getAsnData, resetPagination } = useDashboardASNStore();
    const { params } = store;
    return {
      resetPagination,
      getAsnData,
      params,
      date,
    };
  },
});
</script>
