import { date } from 'quasar';
import { defineStore } from 'pinia';
import { asnApiService } from 'src/services';
import { useSettingStore } from 'src/store/main';
import { masterDataPrefix } from 'src/constants';
import { removeSortOrderFromStorage } from 'src/utils/ms_utlis';

export interface dynamicObj {
  [key: string]: any;
}

export const useDashboardASNStore = defineStore('dashboard_asn_store', {
  state: () => ({
    pagination_size_key: 'PAGINATION_SIZE',
    pagination_size: 10,
    paginationCount: 0,
    total_data: 0,
    loading: true,
    display_data: [] as any[],
    order_by: {} as dynamicObj,
    quickFilterMap: new Map<string, any>(),
    pagination: {
      current_page: 1,
      total_pages: 0,
      page_size: 25,
    },
    params: {
      keyword: '',
      po_number: '',
      order_number: '',
      order_date: '',
      after_date: '',
      before_date: '',
      sort_by: '',
      order: '',
      order_status: '',
    },
    table_columns: {
      customer_name: {
        name: 'customer_name',
        translation_key: 'customer_name',
        actions: true,
        order: 0,
      },
      customer_number: {
        name: 'customer_number',
        translation_key: 'customer_number',
        actions: true,
        order: 1,
      },
      order_date: {
        name: 'order_date',
        translation_key: 'order_date',
        actions: true,
        order: 2,
      },
      requested_delivery_date: {
        name: 'requested_delivery_date',
        translation_key: 'requested_delivery_date',
        actions: true,
        order: 3,
      },
      estimated_delivery_date: {
        name: 'estimated_delivery_date',
        translation_key: 'estimated_delivery_date',
        actions: true,
        order: 4,
      },
      po_number: {
        name: 'po_number',
        translation_key: 'po_number',
        actions: true,
        order: 5,
      },
      order_number: {
        name: 'order_number',
        translation_key: 'order_number',
        actions: true,
        order: 6,
      },
      order_status: {
        name: 'order_status',
        translation_key: 'order_status',
        actions: true,
        order: 7,
      },
    } as dynamicObj,
  }),
  actions: {
    resetPagination() {
      this.pagination = {
        current_page: 1,
        total_pages: 0,
        page_size: 25,
      };
    },
    resetFilter() {
      this.params = {
        keyword: '',
        po_number: '',
        order_number: '',
        order_date: '',
        after_date: '',
        before_date: '',
        sort_by: '',
        order: '',
        order_status: '',
      };
      this.pagination = {
        current_page: 1,
        total_pages: 0,
        page_size: 25,
      };
      removeSortOrderFromStorage('supplier');
      this.order_by = {} as dynamicObj;
      this.quickFilterMap.clear();
    },
    async getColumnPreference(master_lookup_type: string) {
      const key = masterDataPrefix + master_lookup_type.toUpperCase();
      const settings_store = useSettingStore();
      const setting = await settings_store.getSetting(key) as dynamicObj;
      return String(!setting ? '[]' : setting);
    },
    async getAsnData() {
      try {
        this.loading = true;
        const filterObj: any = {};
        this.quickFilterMap.clear(); // Clear existing filters

        for (const [key, value] of Object.entries(this.params)) {
          const data = value as any;
          if (typeof data === 'object') {
            if (data && Object.keys(data).length > 0) {
              filterObj[key] = data.value;
              this.quickFilterMap.set(key, { label: key, value: data.label });
            }
          } else if (data !== '') {
            filterObj[key] = data;
            this.quickFilterMap.set(key, {
              label: key,
              value: data.label ?? data,
            });
          }
        }
        const offset =
          (this.pagination.current_page - 1) * this.pagination.page_size;
        const response = await asnApiService.getAsnDashboard({
          ...filterObj,
          limit: this.pagination.page_size,
          skip: offset,
        });
        if (!response) {
          throw response;
        }
        this.display_data = response?.data as any[];
        this.paginationCount = response?.metadata.total_results;
        this.pagination.total_pages = Math.ceil(
          response.metadata.total_results / this.pagination.page_size,
        );
        this.total_data = response.metadata.total_results;
        this.loading = false;
      } catch (error) {
        throw error;
      }
    },
    async exprtPdf(id: string, sales_order_line_id: string): Promise<any> {
      try {
        const response = await asnApiService.exportPdf(id, sales_order_line_id);
        if (!response) {
          throw response;
        }
        const url = response.data.preview_path;
        const a = document.createElement('a');
        document.body.appendChild(a);
        a.href = url;
        a.setAttribute('download', '');
        a.click();
        document.body.removeChild(a);
      } catch (error) {
        throw error;
      }
    },
    async getSavedColumnPreference(key: string) {
      const settings_store = useSettingStore();
      const saved_columns = await settings_store.getSetting(key) as dynamicObj;
      return String(!saved_columns ? '' : saved_columns);
    },
  },
});
