<template>
  <q-input
    :style="{ width: search_width ? search_width + '%' : '500px' }"
    dense
    v-model="params.keyword"
    autofocus
    @update:model-value="fetchData"
    :debounce="1000"
    :placeholder="$t('search_supplier')"
    outlined
    @keyup="onKeyup"
  >
    <template v-slot:append>
      <f-btn icon="tune" appearance="flat">
        <q-menu
          style="width: 500px; min-height: 250px"
          anchor="bottom start"
          self="top left"
          :offset="[453, 10]"
        >
          <div class="q-pa-md">
            <div class="row q-my-sm">
              <span style="margin-top: 5px">{{ $t('po_number') }}</span>
              <q-space />
              <PoNumber />
            </div>
            <div class="row q-my-sm">
              <span style="margin-top: 5px">{{ $t('order_number') }}</span>
              <q-space />
              <OrderNumber />
            </div>
            <div class="row q-my-sm">
              <span style="margin-top: 5px">{{ $t('order_date') }}</span>
              <q-space />
              <OrderDate />
            </div>
            <div class="row q-my-sm">
              <span style="margin-top: 5px">{{ $t('after_date') }}</span>
              <q-space />
              <AfterDate />
            </div>
            <div class="row q-my-sm">
              <span style="margin-top: 5px">{{ $t('before_date') }}</span>
              <q-space />
              <BeforeDate />
            </div>
            <div class="row q-my-sm">
              <span style="margin-top: 5px">{{ $t('shipment_per_page') }}</span>
              <q-space />
              <q-select
                outlined
                dense
                class="q-mr-sm user-select"
                v-model="pagination.page_size"
                :options="pagination_options"
                @update:model-value="getAsnData"
                :label="$t('shipment_per_page')"
              >
              </q-select>
            </div>
            <div class="float-right q-ml-auto">
              <f-btn
                appearance="secondary"
                class="q-mr-sm mt-20 q-mb-md"
                :label="$t('clear_filters')"
                @click="resetFilters()"
              />
            </div>
          </div>
        </q-menu>
      </f-btn>
    </template>
  </q-input>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { useDashboardASNStore } from '../../store/index';
import BeforeDate from 'src/pages/asn_shipment/components/filter/before_date-filter.vue';
import AfterDate from 'src/pages/asn_shipment/components/filter/after_date-filter.vue';
import PoNumber from 'src/pages/asn_shipment/components/filter/po_number-filter.vue';
import OrderNumber from 'src/pages/asn_shipment/components/filter/order_number-filter.vue';
import OrderDate from 'src/pages/asn_shipment/components/filter/order_date-filter.vue';

export default defineComponent({
  mixins: [],
  props: {
    search_width: {
      type: Number,
    },
  },
  components: {
    BeforeDate,
    AfterDate,
    PoNumber,
    OrderNumber,
    OrderDate,
  },
  methods: {
    resetFilters() {
      this.resetFilter();
      this.fetchData();
      this.removeFiltersClass();
    },
    removeFiltersClass() {
      // remove sort class
      let elements = document.getElementsByClassName('orderBy selected');

      Array.from(elements).forEach((item: any) => {
        item.classList.remove('selected');
      });
    },
    onKeyup(event: any) {
      if (event.key == 'Enter') {
        this.fetchData();
      }
    },
    async fetchData() {
      this.loading = true;
      this.resetPagination();
      await this.getAsnData();
      this.loading = false;
    },

    handleEmptyStatus() {
      if (
        !(
          !this.searchInput ||
          this.searchInput === null ||
          this.searchInput.trim() === ''
        )
      ) {
        return false;
      }

      this.resetFilters();
      return true;
    },

    triggerApplyFilters() {
      const event = new CustomEvent('apply_filters', { detail: {} });
      document.dispatchEvent(event);
    },
    validatePaginationSize() {
      if (this.pagination.page_size <= 50) return;
      this.pagination.page_size = 50;
    },
  },
  mounted() {
    this.validatePaginationSize();
  },
  setup() {
    const dashboard_store = useDashboardASNStore();
    const pagination_options = ['10', '25', '50'];
    const { loading, pagination, params } = storeToRefs(dashboard_store);
    const { getAsnData, resetPagination, resetFilter } = dashboard_store;

    return {
      getAsnData,
      pagination,
      loading,
      searchInput: ref(''),
      oldSearchInput: ref(''),
      showing: ref(false),
      debounceSearchInputFunc: {} as any,
      request_params: {} as dynamicObj,
      filter_data_json_str: '',
      pagination_options,
      resetPagination,
      resetFilter,
      params,
    };
  },
});
</script>
<style lang="scss">
.search-invoices {
  width: 500px;
  padding: 0;
  transition: 0.3s;
}
.user-select {
  width: 227px;
}
</style>
