<template>
  <div class="saved-filter-badge row absolute">
    <template v-for="[key, item] in quickFilterMap" :key="key">
      <q-badge rounded color="primary" class="q-mr-sm capitalize">
        <template v-slot>
          {{ item.value ? item.value : item }}
          <q-icon
            name="close"
            color="white"
            size="xs"
            class="q-ml-xs cursor-pointer"
            style="font-size: 12px !important"
            @click="removeFilter(key)"
          />
        </template>
      </q-badge>
    </template>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useDashboardASNStore } from 'src/pages/asn_shipment/store/index';

export default defineComponent({
  props: {},
  mounted() {
    this.init();
  },
  methods: {
    async init() {
      await this.$nextTick();
    },

    removeFilter(key: string) {
      this.quickFilterMap.delete(key);
      if (key in this.params) {
        this.params[key as keyof typeof this.params] = '';
      }
      this.getDataServer();
    },
    async getDataServer() {
      try {
        this.loading = true;
        await this.getAsnData();
      } catch (err) {
        logError(err);
      } finally {
        this.loading = false;
      }
    },
  },
  setup() {
    const store = storeToRefs(useDashboardASNStore());
    const { getAsnData } = useDashboardASNStore();
    const { params, quickFilterMap, loading } = store;
    return {
      quickFilterMap,
      params,
      loading,
      getAsnData,
    };
  },
});
</script>
