<template>
  <MessageBanner
    v-if="!user_settings[asn_dashboard_setting]"
    :dissmiss_btn="false"
    :back_route="false"
    :message="$t('ACTION_NOT_ALLOWED')"
  />
  <template v-else-if="!isMobile()">
    <SubHeader
      name="asn_shipment_dashboard"
      :label="$t('advance_shipment_dashboard')"
      :show_expiry_alert="true"
    />

    <div class="dashboard-container dashboard-text-color dashboard-main" data-test="asn-dashboard-page">
      <DashboardHeader />
      <q-separator class="seperator" />
      <div class="full-width dashboard-list-area q-my-lg" style="overflow-x: auto;">
        <DocBitsTable
          :rows="tableRows"
          :columns="v2TableColumns"
          row-key="order_number"
          table-id="advance_shipment_table"
          :loading="loading"
          :features="v2TableFeatures"
          :row-actions="v2RowActions"
          :pagination="v2PaginationState"
          :rows-per-page-options="[10, 20, 25, 50]"
          pagination-label="pagination_size"
          :pagination-settings-key="pagination_settings_key"
          no-data-label="no_record_found"
          :column-order="v2ColumnOrder"
          table-class="scroll-height-100vh-265px"
          @update:sorting="handleV2Sort"
          @update:pagination="handleV2Pagination"
          @column-reorder="handleV2ColumnReorder"
          @row-click="handleV2RowClick"
          @row-action="handleV2RowAction"
        >
          <!-- Order Status Column - Custom Stepper -->
          <template #body-cell-order_status="{ row }">
            <div class="custom_stepper">
              <q-stepper
                :model-value="null"
                color="primary"
                header-class="no-wrap"
                flat
                animated
              >
                <q-step
                  :name="1"
                  title=""
                  :done="includeStatus(row.order_status) >= 1"
                />
                <q-step
                  :name="2"
                  title=""
                  :done="includeStatus(row.order_status) >= 2"
                />
                <q-step
                  :name="3"
                  title=""
                  :done="includeStatus(row.order_status) >= 3"
                />
              </q-stepper>
            </div>
          </template>

          <!-- Order Date Column -->
          <template #body-cell-order_date="{ row }">
            {{ formatDateAccordingToPreference(row.order_date) }}
          </template>

          <!-- Requested Delivery Date Column -->
          <template #body-cell-requested_delivery_date="{ row }">
            {{ formatDateAccordingToPreference(row.requested_delivery_date) }}
          </template>

          <!-- Estimated Delivery Date Column -->
          <template #body-cell-estimated_delivery_date="{ row }">
            {{ formatDateAccordingToPreference(row.estimated_delivery_date) }}
          </template>
        </DocBitsTable>
      </div>
    </div>
  </template>

  <!-- Mobile View - Keep existing card layout -->
  <template v-else>
    <SubHeader name="dashboard" label="Dashboard" :show_expiry_alert="true">
    </SubHeader>
    <q-space></q-space>
    <DashboardHeader media_screen="mobile" />
    <div style="margin: 20px 10px">
      <div
        class="card-order q-mb-sm cursor-pointer"
        v-for="item in display_data"
        :key="item.name"
        @click="goToDetail(item?.order_number)"
      >
        <div class="q-pa-sm row">
          <p
            class="col-5 text-primary"
            style="font-weight: 500; display: flex; align-items: center"
          >
            {{ item.order_number }}
          </p>
          <div class="col-7" align="right">
            <div class="stepper-mobile-view">
              <q-stepper
                ref="stepper"
                :model-value="null"
                color="primary"
                header-class="no-wrap"
                flat
                animated
                style="background-color: #f7f7f7 !important"
              >
                <q-step
                  :name="1"
                  title=""
                  :done="(includeStatus(item.order_status) ?? 0) >= 1"
                ></q-step>
                <q-step
                  :name="2"
                  title=""
                  :done="(includeStatus(item.order_status) ?? 0) >= 2"
                ></q-step>
                <q-step
                  :name="3"
                  title=""
                  :done="(includeStatus(item.order_status) ?? 0) >= 3"
                ></q-step>
              </q-stepper>
            </div>
          </div>
        </div>
        <div style="border-bottom: 1px solid grey"></div>
        <div
          class="q-gutter-sm"
          style="
            padding: 10px 10px 30px 10px !important;
            font-size: 13px;
            color: grey;
          "
        >
          <div class="row">
            <div class="col-5" style="text-transform: uppercase">
              {{ $t('customer_no') }}:
            </div>
            <div class="col-6">{{ item.customer_number }}</div>
            <div @click.stop.prevent class="col-1 cursor-pointer" align="right">
              <q-icon flat dense round name="more_horiz" size="20px" />
            </div>
          </div>
          <div class="row">
            <div class="col-5" style="text-transform: uppercase">
              {{ $t('order_date') }}:
            </div>
            <div class="col-6">
              {{ formatDateAccordingToPreference(item.order_date) }}
            </div>
          </div>
          <div class="row">
            <div class="col-5" style="text-transform: uppercase">
              {{ $t('est_mobile_delivery_date') }}:
            </div>
            <div class="col-6">
              {{ formatDateAccordingToPreference(item.estimated_delivery_date) }}
            </div>
          </div>
          <div class="row">
            <div class="col-5" style="text-transform: uppercase">
              {{ $t('po_number') }}:
            </div>
            <div class="col-6">{{ item.po_number }}</div>
          </div>
        </div>
      </div>

      <div class="back-white flex justify-center">
        <div class="row">
          <q-pagination
            v-model="pagination.current_page"
            color="primary"
            :max="pagination.total_pages"
            :max-pages="3"
            input
            boundary-links
            @update:model-value="paginationItemClicked()"
          />
        </div>
      </div>
    </div>
  </template>

  <q-inner-loading :showing="loading" style="z-index: 10000">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { date } from 'quasar';
import { storeToRefs } from 'pinia';
import { isMobile } from 'src/supplier/utils';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { ref, defineComponent } from 'vue';
import DashboardHeader from '../components/DashboardHeader.vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import { useDashboardASNStore } from '../store/index';
import dateUtils from 'src/utils/date';
import dragDropColumn from 'src/mixins/dragDropColumn';
import MessageBanner from 'src/components/MessageBanner.vue';
import generateSavedColumns from 'src/utils/generateSavedColumns';
import { useSettingStore } from 'src/store/Settings/setting.store';
import { useDashboardASNOrderDetail } from 'src/pages/SalesOrderDetail/store/dashboard.store';
import {
  supplier_dashboard_setting,
  advance_shipment_dashboard_columns,
  asn_dashboard_setting,
} from 'src/constants';
import { useImageAuth } from 'src/composables/useImageAuth';
import { DOC2API_URL } from 'src/pages/APIs';
import { DocBitsTable } from 'src/components/Table';
import { getSavedPaginationSize } from 'src/components/Table/PaginationSettings.vue';
import type {
  RowActionItem,
  SortEventPayload,
  PaginationChangePayload,
  RowActionPayload,
  RowClickPayload,
  UnifiedTableColumn,
} from 'src/components/Table';

export default defineComponent({
  el: '#app',
  mixins: [dragDropColumn, generateSavedColumns, dateUtils],
  props: {
    type_name: {
      type: String,
      reqired: true,
      default: 'supplier',
    },
  },
  components: {
    SubHeader,
    MessageBanner,
    DashboardHeader,
    DocBitsTable,
  },
  data() {
    return {
      pagination_settings_key: 'ASN_PAGINATION_SIZE',
      asn_dashboard_setting,
      supplier_dashboard_setting,
      show_table_loader: false,
      advance_shipment_dashboard_columns,
    };
  },
  setup() {
    const dashboard_asn_store = useDashboardASNStore();
    const dashboard_asn_order_detail = useDashboardASNOrderDetail();
    const { datePattern } = useSettingStore();
    const {
      loading,
      table_columns,
      display_data,
      paginationCount,
      params,
      pagination,
    } = storeToRefs(dashboard_asn_store);
    const { getAsnData, exprtPdf, getSavedColumnPreference } = dashboard_asn_store;
    const { getAsnShareToken } = dashboard_asn_order_detail;

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    const { updateSetting, startSettingsFetch } = settings_store;

    const tableColumns = ref();
    tableColumns.value = Object.values(
      JSON.parse(JSON.stringify(table_columns.value)),
    ).map((column: any) => {
      return {
        name: column.name,
        required: true,
        label: column.translation_key,
        field: column.name,
        actions: column.actions,
      };
    });

    const { tokenQueryParam, refreshTokenParam } = useImageAuth();

    return {
      loading,
      display_data,
      user_settings,
      table_columns,
      getAsnData,
      getSavedColumnPreference,
      paginationCount,
      tableColumns,
      dashboard_asn_store,
      dashboard_asn_order_detail,
      getAsnShareToken,
      searchInput: ref(''),
      params,
      current_page: ref(1),
      total_pages: ref(0),
      page_size: ref(5),
      total_records: ref(0),
      isMobile,
      pagination,
      datePattern,
      exprtPdf,
      updateSetting,
      startSettingsFetch,
      tokenQueryParam,
      refreshTokenParam,
    };
  },
  computed: {
    /**
     * Table rows from store display_data
     */
    tableRows(): dynamicObj[] {
      return this.display_data;
    },

    /**
     * V2 Table: Transform table_columns to UnifiedTableColumn format
     */
    v2TableColumns(): UnifiedTableColumn[] {
      if (!this.tableColumns || this.tableColumns.length === 0) {
        return [];
      }

      // Apply saved order from user_settings if available, otherwise use tableColumns order
      const savedColumnsStr = this.user_settings?.[this.advance_shipment_dashboard_columns];
      let orderedColumns = this.tableColumns;

      if (savedColumnsStr && savedColumnsStr !== '') {
        try {
          const savedColumns = JSON.parse(savedColumnsStr);
          const orderMap = new Map(savedColumns.map((col: any, index: number) => [col.name, index]));
          orderedColumns = [...this.tableColumns].sort((a: any, b: any) => {
            const aIndex = orderMap.get(a.name) ?? 999;
            const bIndex = orderMap.get(b.name) ?? 999;
            return (aIndex as number) - (bIndex as number);
          });
        } catch {
          // Use tableColumns order
        }
      }

      return orderedColumns.map((col: any) => ({
        name: col.name,
        label: this.$t(col.label || col.name),
        field: col.name,
        sortable: col.actions === true,
        align: 'left' as const,
      }));
    },

    /**
     * V2 Table: Column order for persisted column reordering
     */
    v2ColumnOrder(): string[] {
      if (!this.tableColumns || this.tableColumns.length === 0) {
        return [];
      }

      // Apply saved order from user_settings if available
      const savedColumnsStr = this.user_settings?.[this.advance_shipment_dashboard_columns];

      if (savedColumnsStr && savedColumnsStr !== '') {
        try {
          const savedColumns = JSON.parse(savedColumnsStr);
          return savedColumns.map((col: any) => col.name);
        } catch {
          // Use tableColumns order
        }
      }

      return this.tableColumns.map((col: any) => col.name);
    },

    /**
     * V2 Table: Feature configuration
     */
    v2TableFeatures() {
      return {
        sorting: true,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: true,
        resizable: false,
        pagination: true,
        columnReorder: true,
        columnSettings: true,
        stickyFirstColumn: false,
        stickyLastColumn: true,
      };
    },

    /**
     * V2 Table: Pagination state (includes sort info)
     */
    v2PaginationState() {
      return {
        sortBy: this.params?.sort_by || null,
        descending: this.params?.order === 'desc',
        page: this.pagination.current_page,
        rowsPerPage: this.pagination.page_size,
        rowsNumber: this.paginationCount || 0,
      };
    },

    /**
     * V2 Table: Row actions configuration
     */
    v2RowActions(): RowActionItem[] {
      return [
        { key: 'export', label: 'export', icon: 'download', color: 'primary' },
        { key: 'share', label: 'share', icon: 'share', color: 'primary' },
      ];
    },
  },
  mounted: function () {
    this.init();
    this.initDragDropColumns('advance_shipment_table', 'label');
    document.addEventListener(
      'advance_shipment_table-column-drop',
      this.onDropColumns,
    );
  },
  unmounted: function () {
    document.removeEventListener(
      'advance_shipment_table-column-drop',
      this.onDropColumns,
    );
  },
  methods: {
    // ========== V2 Table Event Handlers ==========
    async handleV2Sort(payload: SortEventPayload) {
      // Update store params
      this.params.sort_by = payload.column;
      this.params.order = payload.direction;

      // Fetch data with new sort
      await this.getData(true);
    },

    async handleV2Pagination(payload: PaginationChangePayload) {
      this.pagination.current_page = payload.page;
      this.pagination.page_size = payload.rowsPerPage;

      // Fetch data with new pagination
      await this.getData(true);
    },

    handleV2RowClick(payload: RowClickPayload) {
      this.goToDetail(payload.row.order_number);
    },

    async handleV2ColumnReorder(columnNames: string[]) {
      const columnsToSave = columnNames.map((name) => {
        const col = this.tableColumns.find((c: any) => c.name === name);
        return col;
      }).filter(Boolean);

      // Update local state immediately (prevents flicker during save)
      this.tableColumns = columnsToSave;
      this.user_settings[this.advance_shipment_dashboard_columns] = JSON.stringify(columnsToSave);

      // Save to backend
      await this.savedOrderColumns(columnsToSave);
    },

    async handleV2RowAction(payload: RowActionPayload) {
      if (payload.action === 'export') {
        await this.exportPdfPreview(payload.row.order_number, payload.row.sales_order_line_id);
      } else if (payload.action === 'share') {
        await this.copiesMagicLinkAccess(payload.row.order_number);
      }
    },
    // ========== End V2 Table Event Handlers ==========

    async init() {
      this.startSettingsFetch();
      this.pagination.page_size = await getSavedPaginationSize(this.pagination_settings_key);
      this.prepareTableColumns();
      this.getData(true);
    },

    async getData(show_table_loader: boolean) {
      try {
        this.loading = true;
        if (show_table_loader) {
          this.show_table_loader = true;
        }
        await this.getAsnData();
        this.total_records = this.paginationCount;
      } catch (error) {
        logError(error);
      } finally {
        this.loading = false;
        this.show_table_loader = false;
      }
    },

    goToDetail(order_number: string) {
      this.$router.push(`/sales_order_detail/${order_number}`);
    },

    prepareTableColumns() {
      // Apply saved column order from user_settings if available
      const savedColumnsStr = this.user_settings?.[this.advance_shipment_dashboard_columns];
      if (savedColumnsStr && savedColumnsStr !== '') {
        try {
          const savedColumns = JSON.parse(savedColumnsStr);
          // Reorder tableColumns based on saved order
          const orderMap = new Map(savedColumns.map((col: any, index: number) => [col.name, index]));
          this.tableColumns = [...this.tableColumns].sort((a: any, b: any) => {
            const aIndex = orderMap.get(a.name) ?? 999;
            const bIndex = orderMap.get(b.name) ?? 999;
            return (aIndex as number) - (bIndex as number);
          });
        } catch {
          // Keep default order if parsing fails
        }
      }
    },

    onDropColumns() {
      this.savedOrderColumns(this.tableColumns);
    },

    async savedOrderColumns(columns: any) {
      try {
        this.loading = true;
        await this.updateSetting(
          this.advance_shipment_dashboard_columns,
          JSON.stringify(columns),
        );
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    formateDate(strDate: string, dateFormet: string) {
      return date.formatDate(strDate, dateFormet);
    },

    includesDate(date: string) {
      const field = [
        'order_date',
        'requested_delivery_date',
        'estimated_delivery_date',
      ];
      return field.some((keyword) => date.includes(keyword));
    },

    includeStatus(status: string) {
      const statusList = ['Reserved', 'Allocated', 'Picking list printed'];
      if (statusList.includes(status)) {
        return 1;
      } else if (status === 'Delivered') {
        return 2;
      } else if (status === 'Invoiced') {
        return 3;
      }
      return 0;
    },

    resetFilters() {
      // remove sort class
      let elements = document.getElementsByClassName('orderBy selected');

      Array.from(elements).forEach((item: any) => {
        item.classList.remove('selected');
      });
    },

    async paginationItemClicked() {
      try {
        await this.getData(true);
      } catch (error) {
        logError(error);
      }
    },

    async exportPdfPreview(id: string, sales_order_line_id: string) {
      await this.refreshTokenParam();
      await this.dashboard_asn_order_detail.getAsnOrderDataDetail(id);

      // Extract filename
      const getFileName = (path: string, customerPo: string) => {
        if (path) {
          const pathParts = path.split('/');
          const fileName = pathParts[pathParts.length - 1];
          return fileName.replace(/\.[^/.]+$/, '') + '.pdf';
        }
        return `${customerPo}.pdf`;
      };

      try {
        const data = this.dashboard_asn_order_detail.data;
        const fileName = getFileName(data.preview_path, data.customer_po);
        if (!data.preview_path) {
          throw { message: 'Failed to download PDF' };
        }
        const encodedPath = encodeURIComponent(data.preview_path);
        const url = `${DOC2API_URL}/resource/get_file/${data.customer_po}?path=${encodedPath}&download=true&${this.tokenQueryParam}`;

        // Fetch as blob
        const response = await fetch(url, {
          method: 'GET',
          headers: {
            Accept: 'application/pdf',
          },
        });

        if (!response.ok) {
          throw { message: `Failed to download PDF: ${response.status}` };
        }

        const blob = await response.blob();

        // Create a download link
        const blobUrl = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = blobUrl;
        a.download = fileName;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        window.URL.revokeObjectURL(blobUrl);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    async copiesMagicLinkAccess(id: string) {
      try {
        let tokens = await this.getAsnShareToken(id);
        if (tokens.data.token) {
          const baseUrl = window.location.origin as any;
          let shareLink = `${baseUrl as string}/sales_order_detail/${id}/share?token=${tokens.data.token as string}`;
          navigator.clipboard.writeText(shareLink);
          notify.success(this.$t('link_copied_to_clipboard'));
        }
        return;
      } catch (error) {
        notify.error(this.$t('error_internal_occur'));
        logError(error);
      }
    },
  },
});
</script>

