<template>
  <div v-if="media_screen === 'mobile'">
    <div class="row q-mt-md" style="padding-left: 10px">
      <div class="col-12">{{ $t('all_orders') }} {{ `(${total_data})` }}</div>
    </div>
    <div class="row mt-15" style="width: 100%; padding: 0px 10px">
      <div style="width: 85%">
        <div class="dashboard-search-box white-inputs">
          <quickSearch :search_width="95" />
        </div>
      </div>
      <div style="width: 10%">
        <f-btn square @click="refreshFilters">
          <Icon icon="mdi:refresh" width="20" height="20" />
          <q-tooltip>{{ $t('refresh_list') }}</q-tooltip>
        </f-btn>
      </div>
    </div>
  </div>

  <div v-else class="row q-mb-md">
    <div
      style="margin-top: 39px"
      class="row items-start example-container dashboard-title dark-readable"
    >
      <div class="example-cell cursor-pointer" tabindex="0">
        {{ $t('all_orders') }} {{ `(${total_data})` }}
      </div>
    </div>

    <div class="col q-ml-xl">
      <div class="row justify-start">
        <div class="dashboard-search-box q-ml-md mt-20 white-inputs">
          <quickSearch />
        </div>
        <q-space />
        <f-btn
          square
          class="q-mr-sm mt-20"
          @click="refreshFilters"
        >
          <Icon icon="mdi:refresh" width="20" height="20" />
          <q-tooltip>{{ $t('refresh_list') }}</q-tooltip>
        </f-btn>
      </div>
    </div>
  </div>
  <div
    class="row mb-25 relative-position"
    style="margin-bottom: 8px"
    v-if="quickFilterMap.size > 0"
  >
    <div class="dashboard-toggler-area"></div>
    <savedFilterBadges />
  </div>
</template>
<script lang="ts">

import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import quickSearch from './filter/quick-search.vue';
import { useDashboardASNStore } from '../store/index';
import savedFilterBadges from 'src/pages/asn_shipment/components/saved-filter-badges.vue';

export default defineComponent({
  props: {
    type_name: {
      type: String,
      reqired: true,
      default: 'supplier',
    },
    media_screen: {
      type: String,
      reqired: true,
      optional: false,
    },
  },
  components: {
    
    quickSearch,
    savedFilterBadges,
  },
  mounted() {
    document.addEventListener('delete_input_text', this.clearSearchInput);
  },
  methods: {
    clearSearchInput() {
      this.searchInput = '';
    },
    refreshFilters() {
      this.getDataServer();
    },
    async getDataServer() {
      try {
        this.loading = true;
        await this.getAsnData();
        this.total_records = this.paginationCount;
      } catch (err) {
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    resetFilters() {
      const event = new CustomEvent('reset_filters', {});
      document.dispatchEvent(event);
    },
  },
  setup() {
    const dashboard_asn_store = useDashboardASNStore();
    const {
      params,
      loading,
      total_data,
      pagination,
      display_data,
      quickFilterMap,
      paginationCount,
    } = storeToRefs(dashboard_asn_store);
    const { getAsnData } = dashboard_asn_store;
    return {
      getAsnData,
      params,
      loading,
      total_data,
      pagination,
      display_data,
      quickFilterMap,
      paginationCount,
      searchInput: ref(''),
      total_records: ref(0),
    };
  },
});
</script>
